/// Raven `ObjectDie`.
///
/// Source: `oracle/oracle/codemp/game/g_combat.c:22-31`
pub fn ObjectDie(
    self_: *mut gentity_t,
    inflictor: *mut gentity_t,
    attacker: *mut gentity_t,
    damage: c_int,
    meansOfDeath: c_int,
) {
    unsafe {
        if !(*self_).target.is_null() {
            G_UseTargets(self_, attacker);
        }

        // remove my script_targetname
        G_FreeEntity(self_);
    }
}

